\subsubsection{Observable 2.1: Time-Delay Scaling}

\textbf{Key discriminant:} TGL predicts quartic scaling with velocity dispersion:
\begin{equation}
\frac{\Delta t_{\text{TGL}}}{\Delta t_{\text{GR}}} = 1 + \alpha\xi\left(\frac{\sigma_v}{c}\right)^4
\label{eq:time_delay_scaling}
\end{equation}
vs. GR/SIS quadratic: $\Delta t \propto \sigma_v^2$.

\textbf{Physical origin:} Non-minimal coupling creates $\Psi$-dependent Shapiro delay:
\begin{equation}
\Delta t_\gamma^{\text{TGL}} = \Delta t_\gamma^{\text{GR}}\left(1 + \xi\int_{\text{path}}\frac{|\Psi|^2}{M_{\text{Pl}}^2}dl\right)
\label{eq:shapiro_tgl}
\end{equation}

For NFW halo with $|\Psi|^2 \propto \rho_{\text{DM}}$: $\int|\Psi|^2dl \propto \sigma_v^4$ (higher moments dominate).

\textbf{CRITICAL CORRECTION:} From transition ruler (Gráviton paper):
\begin{equation}
\alpha \approx \frac{K_0^2}{GM_{\text{lens}}^2} \sim 10^{16}
\label{eq:alpha_factor}
\end{equation}
where $K_0 = L_*\sqrt{\rho}$ is the universal scaling constant.

\textbf{Revised prediction for typical galaxy} ($M \sim 10^{12}M_\odot$, $\sigma_v = 200$~km/s):
\begin{equation}
\frac{\Delta t_{\text{TGL}}}{\Delta t_{\text{GR}}} \approx 1 + 10^{16} \times 0.1 \times \left(\frac{2\times10^5}{3\times10^{10}}\right)^4 \approx \mathbf{1.1}
\label{eq:time_delay_numeric}
\end{equation}

